        verified=fresh(true);startInvite(verified);RelayApi.last().answer(invitation(),200);verified.ticket="f".repeat(32);check(verified.promptAction()==null,"in-memory ticket mismatch");verified.disconnectAction();check(verified.invitationArtifacts==null&&verified.promptAction()==null,"stop clears artifact expectations");pass("ticket mismatch and stop never reuse the prior artifact expectations");
        SetupRecovery.Backoff b=new SetupRecovery.Backoff();for(long expected:new long[]{1000,2000,4000,8000,-1,-1})check(b.nextDelay()==expected,"bounded exponential backoff");b.reset();check(b.nextDelay()==1000,"reset");pass("bounded retry budget has four increasing delays then stops");
        MainActivityHarness a=fresh(false);a.config=new EnrollmentStore.Config(BuildConfig.PUBLIC_RELAY_ORIGIN,"d".repeat(64),0L);a.prefs.edit().putBoolean("setup_continue",true).commit();a.loadProtocol(0);a.continueAction();check(a.upgrade&&RelayApi.requests.isEmpty(),"legacy null device ID must use upgrade instead of enrollment");pass("actual Activity migration branch retains upgrade for legacy zero-expiry records without a device ID");
        for(int protocol:new int[]{0,4}) {a=fresh(false);a.config=new EnrollmentStore.Config(BuildConfig.PUBLIC_RELAY_ORIGIN,"c".repeat(32),"d".repeat(64),false);EnrollmentStore.Config identity=a.config;a.prefs.edit().putBoolean("setup_continue",true).commit();a.loadProtocol(protocol);a.continueAction();check(!a.upgrade&&a.config==identity&&RelayApi.last().path.equals("/v1/service")&&RelayApi.posts("/v1/enroll")==0,"new pending identity resumes discovery with no migration or new ID");}pass("actual Activity migration branch resumes a pending public identity before or after the protocol marker is saved");
        a=fresh(true);EnrollmentStore.Config registered=a.config;a.loadProtocol(4);a.continueAction();check(!a.upgrade&&a.config==registered&&RelayApi.requests.isEmpty(),"registered v4 identity is not enrolled again");pass("actual Activity migration branch leaves an existing registered v4 identity intact");
        a=fresh(false);a.enrollAction();String id=a.config.deviceId,token=a.config.token;RelayApi.last().answer(null,0);
        for(int i=0;i<4;i++){a.main.next();RelayApi.last().answer(null,0);}check(RelayApi.requests.size()==5&&a.main.tasks.isEmpty()&&!a.busy&&a.setupExhausted,"five discovery attempts only");check(RelayApi.posts("/v1/enroll")==0&&a.config.deviceId.equals(id)&&a.config.token.equals(token),"no enrollment before discovery");pass("offline discovery stops without allocating another identity or submitting enrollment");
        a=fresh(false);a.enrollAction();RelayApi.last().answer(discovery(),200);check(RelayApi.last().method.equals("GET")&&RelayApi.last().path.equals("/v1/device/pairing"),"read existing identity first");RelayApi.last().answer(null,404);RelayApi.Request first=RelayApi.last();check(first.method.equals("POST"),"enroll once");first.answer(null,0);a.main.next();check(RelayApi.last().method.equals("GET"),"read before retry");RelayApi.last().answer(state("idle"),200);check(a.config.enrolled()&&RelayApi.posts("/v1/enroll")==1,"lost enrollment response recovered by GET");pass("lost enrollment acknowledgement recovers via authenticated read with the same identity");
        a=fresh(false);PreviewService.instance=new PreviewService();a.enrollAction();RelayApi.last().answer(discovery(),200);RelayApi.last().answer(state("approved"),200);check(RelayApi.posts("/v1/device/pairing")==0&&RelayApi.last().method.equals("GET"),"read existing pairing instead of replace");RelayApi.last().answer(state("approved"),200);check(RelayApi.posts("/v1/device/pairing")==0&&TrustedGrant.trusted==null,"existing state preserved");pass("resuming enrollment preserves any existing invitation or approved remote state");
        a=fresh(false);a.enrollAction();RelayApi.last().answer(discovery(),200);RelayApi.last().answer(null,503);first=RelayApi.last();first.answer(null,0);a.main.next();RelayApi.last().answer(null,503);RelayApi.Request second=RelayApi.last();check(first.body.getString("device_id").equals(second.body.getString("device_id"))&&first.body.getString("device_token").equals(second.body.getString("device_token")),"idempotent identity unchanged");pass("interrupted registry activation retries only the exact idempotent enrollment identity");
        a=fresh(false);a.enrollAction();RelayApi.Request late=RelayApi.last();a.onPause();late.answer(discovery(),200);check(RelayApi.requests.size()==1&&!a.busy&&late.cancelled,"late discovery fenced");pass("leaving Activity cancels work and rejects a late discovery callback");
        a=fresh(true);startInvite(a);late=RelayApi.last();a.onPause();late.answer(json("protocol_version",4,"ticket","e".repeat(32),"expires_at",JSONObject.NULL,"pairing_expires_at",System.currentTimeMillis()/1000+300),200);check(a.ticket==null,"no late ticket");a.visible=true;a.setupPaused=true;a.continueAction();check(RelayApi.last().method.equals("GET")&&RelayApi.posts("/v1/device/pairing")==1,"resume reads unknown result");RelayApi.last().answer(state("pending"),200);check("123456".equals(a.code)&&a.claim!=null,"same request recovered");pass("leaving during invitation preserves an unknown-result marker and resumes the existing claim");
        a=fresh(true);startInvite(a);RelayApi.last().answer(null,0);check(RelayApi.last().method.equals("GET"),"unknown POST read");RelayApi.last().answer(state("waiting"),200);a.continueAction();check(a.invitationUncertain&&a.ticket==null&&RelayApi.posts("/v1/device/pairing")==1,"no blind new invitation");pass("lost invitation text is explained and never regenerated automatically");
        a=fresh(true);startInvite(a);RelayApi.last().answer(null,0);RelayApi.last().answer(state("approved"),200);a.continueAction();check(TrustedGrant.trusted==null&&RelayApi.posts("/v1/device/pairing")==1,"no new authorization");pass("server approved state does not manufacture local consent or replace the connection");
        a=fresh(true);startInvite(a);late=RelayApi.last();a.disconnectAction();late.answer(json("protocol_version",4,"ticket","e".repeat(32),"expires_at",JSONObject.NULL,"pairing_expires_at",System.currentTimeMillis()/1000+300),200);a.continueAction();check(a.ticket==null&&!a.prefs.getBoolean("setup_continue",false)&&a.prefs.getString("invitation_identity","").isEmpty(),"stop prevents continuation");pass("owner stop clears setup intent and fences late invitation success");
        a=fresh(true);startInvite(a);late=RelayApi.last();a.onPause();a.visible=true;a.switchAction("https://other.example");late.answer(state("pending"),200);check(a.config.origin().equals("https://other.example")&&a.claim==null,"old relay ignored");pass("switching relay rejects callbacks belonging to the old identity and server");
        a=fresh(true);a.prefs.edit().putBoolean("setup_continue",true).commit();a.continueAction();check(RelayApi.requests.isEmpty(),"wait for permission");PreviewService.instance=new PreviewService();SessionService.notifications=false;a.continueAction();check(RelayApi.requests.isEmpty(),"still need notifications");SessionService.notifications=true;a.continueAction();a.continueAction();check(RelayApi.posts("/v1/device/pairing")==1,"automatic once");pass("first setup continues once after required system permissions without another invite tap");
        a=fresh(true);PreviewService.instance=new PreviewService();TrustedGrant.unreadable=true;a.prefs.edit().putBoolean("setup_continue",true).commit();a.continueAction();a.inviteAction();check(a.storageError&&RelayApi.requests.isEmpty(),"cannot erase unreadable consent");pass("unreadable saved consent blocks automatic continuation and explicit invitation replacement");
